"""Argument parsing and lazy server/client dispatch."""

import argparse
import os

from .domain import APIError, parse_timestamp


def _nonempty(value):
    if not value:
        raise argparse.ArgumentTypeError("must not be empty")
    return value


def _port(value):
    number = int(value)
    if not 0 <= number <= 65535:
        raise argparse.ArgumentTypeError("must be between 0 and 65535")
    return number


def _rate_limit(value):
    number = int(value)
    if number < 1:
        raise argparse.ArgumentTypeError("must be at least 1")
    return number


def _timestamp(value):
    try:
        return parse_timestamp(value)
    except APIError as error:
        raise argparse.ArgumentTypeError(error.message) from None


def _client_options(parser):
    # Suppressed defaults preserve options supplied before the token create leaf.
    parser.add_argument("--server", default=argparse.SUPPRESS)
    parser.add_argument("--token", default=argparse.SUPPRESS)


def _parser():
    parser = argparse.ArgumentParser(prog="linkvault")
    commands = parser.add_subparsers(dest="command", required=True)

    serve = commands.add_parser("serve")
    serve.add_argument("--db", required=True)
    serve.add_argument("--admin-key", required=True, type=_nonempty)
    serve.add_argument("--port", type=_port, default=8000)
    serve.add_argument("--rate-limit", type=_rate_limit, default=60)
    serve.add_argument("--fake-clock", type=_timestamp)

    token = commands.add_parser("token")
    _client_options(token)
    token_commands = token.add_subparsers(dest="token_command", required=True)
    create = token_commands.add_parser("create")
    _client_options(create)
    create.add_argument("--admin-key", required=True, type=_nonempty)

    shorten = commands.add_parser("shorten")
    _client_options(shorten)
    shorten.add_argument("url")
    shorten.add_argument("--slug")
    shorten.add_argument("--expires-in", type=int)

    listing = commands.add_parser("list")
    _client_options(listing)
    for name in ("stats", "delete"):
        command = commands.add_parser(name)
        _client_options(command)
        command.add_argument("slug")
    return parser


def main(argv=None):
    parser = _parser()
    try:
        args = parser.parse_args(argv)
        if args.command != "serve":
            args.server = getattr(args, "server", os.environ.get("LINKVAULT_SERVER"))
            args.token = getattr(args, "token", os.environ.get("LINKVAULT_TOKEN"))
            if not args.server:
                parser.error("--server or LINKVAULT_SERVER is required")
            if args.command != "token" and not args.token:
                parser.error("--token or LINKVAULT_TOKEN is required")
    except SystemExit as error:
        return error.code

    if args.command == "serve":
        from . import server

        return server.run(args)

    from . import client

    return client.run(args)

"""Small urllib client with explicit HTTP status and output handling."""

from http.client import HTTPException
import json
import sys
from urllib.error import HTTPError, URLError
from urllib.parse import quote
from urllib.request import HTTPRedirectHandler, Request, build_opener

from .domain import json_bytes


class _NoRedirect(HTTPRedirectHandler):
    def redirect_request(self, request, response, code, message, headers, new_url):
        return None


def run(args):
    method, path, body = "GET", "/v1/links", None
    headers = {}
    if args.command == "token":
        method, path = "POST", "/v1/tokens"
        headers["X-Admin-Key"] = args.admin_key
    else:
        headers["Authorization"] = "Bearer " + args.token
        if args.command == "shorten":
            method = "POST"
            value = {"url": args.url}
            if args.slug is not None:
                value["slug"] = args.slug
            if args.expires_in is not None:
                value["expires_in"] = args.expires_in
            body = json_bytes(value)
            headers["Content-Type"] = "application/json"
        elif args.command in ("stats", "delete"):
            path += "/" + quote(args.slug, safe="")
            if args.command == "delete":
                method = "DELETE"

    try:
        request = Request(args.server.rstrip("/") + path, data=body,
                          headers=headers, method=method)
        try:
            response = build_opener(_NoRedirect()).open(request, timeout=5)
        except HTTPError as error:
            # HTTPError is also a response, and must precede URLError handling.
            response = error
        with response:
            status = response.code
            raw = response.read()
    except (URLError, OSError, HTTPException, ValueError) as error:
        print("Connection failure: " + str(error), file=sys.stderr)
        return 3

    success = 200 <= status < 300
    if status == 204:
        return 0
    try:
        value = json.loads(raw.decode("utf-8"))
    except (UnicodeError, ValueError):
        if success:
            print("Invalid JSON response", file=sys.stderr)
            return 3
        # Redirects and non-API peers may have empty or non-JSON error bodies.
        value = {"error": {"code": "http_error", "message": "HTTP " + str(status)}}
    output = sys.stdout if success else sys.stderr
    print(json_bytes(value).decode("utf-8"), file=output)
    return 0 if success else 1
